/* ==========================================================
Global Spirit Group — Mobile Responsiveness Patch for Alberta-Hub
========================================================== */

/* 1. Жесткий запрет горизонтального скролла на уровне страницы */
html, body {
max-width: 100vw;
overflow-x: hidden !important;
margin: 0;
padding: 0;
-webkit-text-size-adjust: 100%;
}

/* 2. Универсальное поведение для всех блоков и контейнеров */
*, *::before, *::after {
box-sizing: border-box;
}

/* 3. Адаптация основного контейнера и хедера */
.container, header, main, .hub-wrapper, .slide-container {
width: 100% !important;
max-width: 100% !important;
padding-left: 16px !important;
padding-right: 16px !important;
margin-left: auto !important;
margin-right: auto !important;
}

/* 4. Медиа-запрос для смартфонов (ширина экрана до 768px) */
@media screen and (max-width: 768px) {
/* Заголовки: уменьшаем размер, чтобы не ломали верстку */
h1 {
font-size: 1.8rem !important;
line-height: 1.2 !important;
}
h2 {
font-size: 1.4rem !important;
}
p, span, li {
font-size: 0.95rem !important;
}

/* Карточки, колонки и слайды — выстраиваем в одну колонку */
.grid, .flex-row, .columns, .slide-content {
display: flex !important;
flex-direction: column !important;
width: 100% !important;
gap: 12px !important;
}

/* Слайдер / Питч-дек карточки */
.pitch-deck, .slide, .card {
width: 100% !important;
min-width: 0 !important;
padding: 12px !important;
margin-bottom: 16px !important;
}

/* Кнопки управления и навигации (Назад / Далее) */
.nav-buttons, .slide-controls {
display: flex !important;
justify-content: space-between !important;
width: 100% !important;
gap: 8px !important;
}

.nav-buttons button, .slide-controls a {
flex: 1 !important;
padding: 12px 8px !important;
text-align: center !important;
font-size: 0.9rem !important;
}

/* Изображения и видео */
img, video, iframe {
max-width: 100% !important;
height: auto !important;
}
}

